package android.graphics; import android.os.Handler; public class SurfaceTexture { public interface OnFrameAvailableListener { void onFrameAvailable(SurfaceTexture t); } public static SurfaceTexture last; private OnFrameAvailableListener listener; public int outstanding,acquired; public SurfaceTexture(int name){last=this;} public void setDefaultBufferSize(int w,int h){} public void setOnFrameAvailableListener(OnFrameAvailableListener l,Handler h){listener=l;} public void setOnFrameAvailableListener(OnFrameAvailableListener l){listener=l;} public void signal(){listener.onFrameAvailable(this);} public void render(){if(++outstanding>1)throw new AssertionError("Released a second surface buffer before the EGL consumer acquired the first");} public void updateTexImage(){if(outstanding!=1)throw new AssertionError("No pending buffer");outstanding=0;acquired++;} public void getTransformMatrix(float[] matrix){} public void release(){} }
